{"code":"const searchResult = await callTool('search_flights', {from: 'BLR', to: 'SYD', maxPrice: 40000});
const flights = searchResult.flights || [];
// Get baggage policies in parallel
const policyPromises = flights.map(f => callTool('get_baggage_policy', {flightId: f.id}));
const policies = await Promise.all(policyPromises);
// Merge data
const enriched = flights.map((f, idx) => {
  const p = policies[idx];
  return {
    id: f.id,
    airline: f.airline,
    price: f.price,
    checkedKg: p ? p.checkedKg : null
  };
});
// Filter for checkedKg >= 20 and not null
const filtered = enriched.filter(e => e.checkedKg !== null && e.checkedKg >= 20);
// Sort by price ascending (already sorted but ensure)
filtered.sort((a,b)=> a.price - b.price);
// Take up to three
const topThree = filtered.slice(0,3);
return {options: topThree, sampleData: true, explanation: `Found ${topThree.length} flights under ₹40,000 with at least 20 kg checked baggage.`};"}

